function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 200) return 'matrix needs 1 to 200 rows.';
  const cols = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (cols < 1 || cols > 200) return 'Each row needs 1 to 200 cells.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    if (row.some(cell => cell !== '0' && cell !== '1')) return "Each cell is '0' or '1'.";
  }
  return null;
}

