function maximalRectangle(matrix) {
  const rows = matrix.length, cols = matrix[0].length;
  let best = 0;
  for (let top = 0; top < rows; top++)
    for (let lft = 0; lft < cols; lft++)
      for (let bottom = top; bottom < rows; bottom++)
        for (let rgt = lft; rgt < cols; rgt++) {
          let full = true;
          for (let r = top; r <= bottom && full; r++)
            for (let c = lft; c <= rgt; c++)
              if (matrix[r][c] !== '1') { full = false; break; }
          if (full) best = Math.max(best, (bottom - top + 1) * (rgt - lft + 1));
        }
  return best;
}

