function generate(rand, size) {
  const rows = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const cols = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const density = size === 'large' ? 0.85 + rand() * 0.14 : rand();
  const matrix = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? '1' : '0')));
  return [matrix];
}
